-- 004 - Devices with a session and rotating refresh tokens (07-BACKEND.md).
-- installation_id is generated by the app at install time; the same phone can host
-- several users, so it is unique per user and not a primary key.
-- Reversal: drop table refresh_tokens; drop table devices;
create table devices (
  id uuid primary key,
  user_id uuid not null references users (id) on delete cascade,
  installation_id uuid not null,
  name text not null check (char_length(name) between 1 and 80),
  platform text not null default 'android' check (platform in ('android')),
  app_version text not null check (char_length(app_version) <= 32),
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  revoked_at timestamptz,
  unique (user_id, installation_id)
);

create table refresh_tokens (
  id uuid primary key,
  user_id uuid not null references users (id) on delete cascade,
  device_id uuid not null references devices (id) on delete cascade,
  family_id uuid not null,
  token_hash text not null unique,
  expires_at timestamptz not null,
  rotated_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

create index refresh_tokens_user_idx on refresh_tokens (user_id);
create index refresh_tokens_family_idx on refresh_tokens (family_id);
